// Rendering for this feature. State changes are handled by app.js and the domain models.
function photoSlots(p){return`<div class="field"><span class="field-label">My photos · at least one</span><div class="photo-slots" id="profile-photos" tabindex="-1">${p.photos.map((src,i)=>`<div class="photo-slot"><img src="${esc(src)}" alt="Your photo ${i+1}"><button class="photo-remove" data-action="photo-remove" data-value="${i}" aria-label="Remove photo ${i+1}">${icon('close')}</button></div>`).join('')}${p.photos.length<3?`<label class="photo-slot photo-add"><input type="file" accept="${PhotoInput.accept}" ${modal?.photoPending?'disabled':''} data-photo-input aria-label="Add a photo">${icon('plus')}<span aria-live="polite">${modal?.photoPending?'Preparing…':'Add photo'}</span></label>`:''}</div>${fieldError('photos')}<p class="caption">${icon('lock')} Hidden until you and your date both say yes after meeting.</p></div>`;}
async function addPhoto(file){
  const owner=modal;if(owner?.type!=='onboarding'||owner.photoPending)return;
  if(owner.draft.photos.length>=3){toast('You can add up to 3 photos.');return;}
  captureProfileFields();owner.photoPending=true;renderModal();
  try{
    const photo=await PhotoInput.prepare(file);
    if(modal!==owner)return;
    captureProfileFields();owner.draft.photos=[...owner.draft.photos,photo];delete owner.errors.photos;persistDraft();
  }catch(error){if(modal===owner)toast(error.message);}
  finally{delete owner.photoPending;if(modal===owner)renderModal();}
}
function factChip(label,graphic,missing=false,step=0){return`<button class="fact-chip ${missing?'missing':''}" data-action="onboarding" data-profile-step="${step}">${icon(graphic)}${esc(label)}${missing?icon('plus'):''}</button>`;}
function answerTile(label,text,action,extra=''){return`<button class="answer-tile" data-action="${action}" ${extra}><span class="tile-label">${label}</span><span class="tile-text">${text}</span><span class="tile-edit" aria-hidden="true">${icon('edit')}</span></button>`;}
function profilePage(){
  const p=state.profile,bills=p.billPreferences.map(v=>esc(Dating.billChoices(p).find(c=>c.id===v)?.title||v)),days=state.availability.windows.length;
  const facts=[p.education?factChip(p.education,'flower'):factChip('Education','flower',true),p.energy?factChip(p.energy,'people',false,2):factChip('Energy','people',true,2),p.intent?factChip(p.intent,'heart',false,3):factChip('Intentions','heart',true,3),Number.isInteger(p.height)?factChip(p.height+' cm','mountain'):factChip('Height','mountain',true),p.drinking?factChip('Drinks: '+p.drinking.toLowerCase(),'coffee',false,2):factChip('Drinking','coffee',true,2),p.workout?factChip('Works out: '+p.workout.toLowerCase(),'heart',false,2):factChip('Workout','heart',true,2),factChip(p.interests.length?`Interests (${p.interests.length})`:'Interests','coffee',!p.interests.length,3),factChip(p.values.length?`Values (${p.values.length})`:'Values','spark',!p.values.length,3)].join('');
  return`<div class="profile-header"><span class="profile-photo-stack" aria-hidden="true"><span>${p.name?esc(p.name.charAt(0).toUpperCase()):icon('user')}</span></span><div class="profile-header-copy"><h1 class="page-title profile-name" tabindex="-1">${p.name?esc(p.name):'Your profile'}${p.verification==='verified-demo'?`<span class="verified-mark" aria-label="Verified in demo only">${icon('seal')}</span>`:p.complete?`<span class="verified-mark" aria-label="Profile complete, identity not verified">${icon('check')}</span>`:''}</h1><p>${p.age?esc(p.age)+' · ':''}${p.verification==='verified-demo'?'ID verified (demo)':'Your face stays a mystery'}</p></div></div>
${!p.complete?`<button class="complete-pill" data-action="onboarding">${icon('warning',true)}${state.drafts.profile?'Continue your profile':'Complete your profile'}</button>`:''}<div class="fact-chips" aria-label="Profile details">${facts}</div>
<div class="stat-strip" aria-label="Your dating record"><span><strong>${state.record.dates}</strong>${state.record.dates===1?'date':'dates'}</span><span class="${state.record.noShows?'warn':''}"><strong>${state.record.noShows}</strong>no-shows</span><span class="${state.record.lateCancels?'warn':''}"><strong>${state.record.lateCancels}</strong>late cancels</span></div>
<section class="section"><h2>My photos</h2><div class="panel photos-panel"><div class="photo-grid">${[0,1,2].map(i=>p.photos[i]?`<img src="${esc(p.photos[i])}" alt="Your photo ${i+1}">`:`<span class="photo-empty" aria-hidden="true">${icon('plus')}</span>`).join('')}</div><div class="photos-foot"><p><strong>Hidden until it’s mutual.</strong> Tip: one clear, recent photo of your face.</p>${button('Edit','onboarding','primary','data-profile-step="0"','')}</div></div></section><section class="section"><h2>My answers</h2><div class="tile-grid">${answerTile('My vibe',p.energy||p.activity?`${esc(p.energy||'Energy not set')}<br>${esc(p.activity||'')}`:'Tell us your energy','onboarding','data-profile-step="2"')}${answerTile('My lifestyle',p.drinking||p.workout||p.familyPlans?[p.workout&&'Works out '+p.workout.toLowerCase(),p.drinking&&'Drinks '+p.drinking.toLowerCase(),p.familyPlans].filter(Boolean).map(esc).join('<br>'):'Drinking, workout, family','onboarding','data-profile-step="2"')}${answerTile('Faith & background',[p.religion,p.ethnicity].filter(v=>v&&v!=='Prefer not to say').map(esc).join('<br>')||'Private · optional','onboarding','data-profile-step="1"')}${answerTile('Bill comfort',bills.length?bills.join('<br>'):'Choose what feels fair','profile-bill')}${answerTile('Who I’d like to meet',state.savedPreferences?'A saved type you can reuse':'Explore your type','navigate','data-view="home"')}${answerTile('When I’m free',days?`${days} day${days>1?'s':''} saved`:'Pick days & places','navigate','data-view="availability"')}</div></section><section class="section"><h2>My interests</h2><div class="tile-grid">${answerTile('Currently into',p.interests.length?p.interests.slice(0,3).map(esc).join(', ')+(p.interests.length>3?`, +${p.interests.length-3}`:''):'Add a few interests','onboarding','data-profile-step="3"')}${answerTile('What I value',p.values.length?p.values.slice(0,3).map(esc).join(', ')+(p.values.length>3?`, +${p.values.length-3}`:''):'Add your values','onboarding','data-profile-step="3"')}</div></section><button class="plus-banner" data-action="membership"><span><strong>blinddate<span>+</span></strong><span>${state.previewPlan?'Demo membership active':`First month ${Plans.money(Plans.monthly.intro)} · save ${Plans.savingPercent()}% yearly`}</span></span>${icon('arrow')}</button><section class="section"><h2>Settings</h2><div class="group-card appearance-card"><div><span class="row-icon">${icon(state.theme==='dark'?'moon':'sun')}</span><strong>Theme</strong></div><div class="segmented" role="group" aria-label="Theme"><button data-action="theme" data-value="dark" aria-pressed="${state.theme==='dark'}" class="${state.theme==='dark'?'selected':''}">Dark</button><button data-action="theme" data-value="light" aria-pressed="${state.theme==='light'}" class="${state.theme==='light'?'selected':''}">Light</button></div></div><div class="group-card">${row(p.verification==='verified-demo'?'Verified (demo)':'Verify my identity',p.verification==='verified-demo'?'Your date sees a Verified badge':'ID and a selfie · free for everyone','seal','verify','','violet')}${row('Safety and privacy','Your face and full profile stay hidden','shield','safety','','mint')}${row('Edit my profile','Age, education, personality and values','edit','onboarding')}</div><button class="button secondary wide-pill" data-action="auth-log-out">Log out</button><button class="button wide-pill" data-action="reset">Reset prototype</button><p class="page-note">Profiles, drafts and current date discussions are stored in this browser. Partner replies and notifications are simulated.<br>blinddate prototype · v0.6</p></section>`;}


function membershipPage() {
  const yearly=state.plan==='annual',M=Plans.monthly,Y=Plans.annual,current=state.previewPlan;
  const planCard=(id,badge,title,price,unit,detail,points)=>`<button class="plan-card ${state.plan===id?'selected':''} ${id==='annual'?'best':''}" data-action="billing" data-value="${id}" aria-pressed="${state.plan===id}"><span class="plan-badge">${badge}</span><span class="plan-title">${title}</span><span class="plan-price">${price}<small>${unit}</small></span><span class="plan-detail">${detail}</span><ul>${points.map(x=>`<li>${icon('check')}${x}</li>`).join('')}</ul><span class="plan-radio" aria-hidden="true">${state.plan===id?icon('check'):''}</span></button>`;
  const table=`<div class="compare-table" role="table" aria-label="Compare plans"><div class="compare-row head" role="row"><span role="columnheader"></span><span role="columnheader">Free</span><span role="columnheader">Monthly</span><span role="columnheader">Yearly</span></div>${Plans.comparison.map(([label,...cells])=>`<div class="compare-row" role="row"><span role="rowheader">${esc(label)}</span>${cells.map((c,i)=>`<span role="cell" class="${i===2?'yearly':''}">${esc(c)}</span>`).join('')}</div>`).join('')}</div>`;
  const status=current?`<section class="panel member-status"><span class="success-pill">${icon('check')} blinddate+ ${current==='annual'?'Yearly':'Monthly'} is active (demo)</span><p>Records are unlocked, you’re introduced first${current==='annual'?', partner perks and your free late cancellation are on':''}.</p>${button('End demo membership','end-membership','secondary','','')}</section>`:'';
  return `${pageHeading('blinddate+','Meet with<br><em>more confidence.</em>','Know who you’re meeting, get introduced first, and make every first hello easier.')}${status}<div class="value-props"><span>${icon('star')}<strong>Know before you go</strong>Rating and show-up record before every date</span><span>${icon('spark')}<strong>Introduced first</strong>Priority when a new match fits you</span><span>${icon('shield')}<strong>Risk-free start</strong>Money back if no introduction in 30 days</span></div><div class="plan-cards" role="group" aria-label="Choose a plan">${planCard('annual',`Best value · save ${Plans.savingPercent()}%`,'Yearly',Plans.money(Plans.perMonth(Y)),'/month',`${Plans.money(Y.price)} billed once a year. About ${Plans.money(Plans.firstYearSaving())} less than paying monthly in your first year.`,[`${Y.credits} date credits a month`,'Partner restaurant perks','1 free late cancellation every 3 months','Price locked while you stay'])}${planCard('monthly','New members · 50% off',`Monthly`,Plans.money(M.intro),' first month',`Then ${Plans.money(M.price)}/month. Cancel anytime.`,[`${M.credits} date credits a month`,'Records before every date','Introduced first'])}</div>${current?'':button(yearly?`Start yearly · ${Plans.money(Y.price)}`:`Start for ${Plans.money(M.intro)}`,'select-plan','primary plan-cta','','arrow')}<p class="guarantee-line">${icon('shield')} ${esc(Plans.guarantee)}</p><section class="section"><h2>Compare plans</h2>${table}</section><section class="section"><h2>Questions</h2><div class="group-card faq">${[['Can I cancel?','Yes. Monthly plans stop renewing whenever you choose. Yearly plans run to the end of the year you paid for.'],['What’s a date credit?','One arranged first date: introduction, plan coordination and a reserved table at a partner venue. Food and drinks are always paid separately.'],['What if nobody fits me?','If we can’t introduce you to anyone in your first 30 days, you get your first payment back. You can also stretch age and distance slightly.'],['Is safety part of the paid plan?','No. Check-ins, verification and reporting are free for everyone, always.']].map(([q,a])=>`<details><summary>${q}${icon('down')}</summary><p>${a}</p></details>`).join('')}</div></section><p class="page-note">Proposed launch pricing in CAD, before tax. Meals and drinks separate. Demo: no payment or subscription is created.</p>`;
}

